// 1. 从输入中获取AI生成的JSON字符串
//    n8n中，$json.output 会直接获取名为 'output' 的输入字段
const llmOutput = $json.output;

// 2. 清理字符串，提取纯净的JSON部分
//    这个正则表达式会找到被包裹在第一个'{'和最后一个'}'之间的所有内容
//    's' 标志让 '.' 可以匹配换行符，这对于处理多行JSON至关重要
const jsonMatch = llmOutput.match(/{.*}/s);

// 3. 检查是否找到了匹配项
if (!jsonMatch || jsonMatch.length === 0) {
  throw new Error("无法在输入中找到有效的JSON字符串。");
}

const cleanJsonString = jsonMatch[0];
let parsedData;

// 4. 解析JSON字符串为JavaScript对象
try {
  parsedData = JSON.parse(cleanJsonString);
} catch (error) {
  throw new Error(`JSON解析失败: ${error.message}. 清理后的字符串为: ${cleanJsonString}`);
}

// 5. 返回拆分好的数据对象
//    这个对象的键（Title, Summary, CoverImagePrompt）
//    将成为Code节点的输出字段，供后续节点使用
return {
  Title: parsedData.Title,
  Summary: parsedData.Summary,
  CoverImagePrompt: parsedData.CoverImagePrompt
};

// 获取上一个节点传入的、已经平整化后的数据项
const item = items[0];

// 1. 定义你的JSON模板 (已移除 content_source_url)。
const template = [{
  // 直接从顶层获取 title 字段
  "title": item.json.title,

  // 直接从顶层获取 media_id 字段
  "thumb_media_id": item.json.media_id,

  "author": "AI乌托邦KKKK", // 在这里修改您的作者名

  // 直接从顶层获取 summary 字段
  "digest": item.json.summary,

  "show_cover_pic": 1,
  "content": "", // 先留空，马上进行填充
}];


// 2. 准备最终的文章正文HTML
// 首先，从顶层获取名为 article 的HTML内容
let htmlContent = item.json.article;

// 其次，定义那个需要被移除的图片占位符的完整HTML
const placeholderHtml = `<p style="text-align: center; color: #888; background-color: #f9f9f9; border: 1px dashed #ccc; padding: 30px; margin: 25px 0; border-radius: 5px;">[-- 此处应插入图片 --]</p>`;

// 最后，将占位符直接替换为空字符串（''），即彻底删除它
htmlContent = htmlContent.replace(placeholderHtml, '');


// 3. 将处理完成的、不含任何配图的HTML，填充到模板的 content 字段中
template[0].content = htmlContent;

// 4. 将最终构建好的对象转换为JSON字符串
const content = JSON.stringify(template);

// 5. 返回下一个节点所需的最终输出
return {
  json: {
    content: content
  }
};

