// 1. 获取上一个节点传入的完整文本内容
// 请确保这里的 '核心选题' 与您输入Item的字段名完全一致
const fullText = $json['核心选题'];

// 2. 定义我们要查找的关键词
const key = '选题切入点';

// 3. 使用关键词将文本分割成两部分
const parts = fullText.split(key);

// 4. 进行安全检查并提取内容
// 如果parts数组长度大于1，说明关键词找到了
if (parts.length > 1) {
  // 我们需要的是关键词后面的那部分内容，即数组的第二个元素 parts[1]
  // .trim() 用于去除可能存在的多余空格和换行符
  const topicAngle = parts[1].trim();

  // 5. 将提取出的内容放入一个新的字段 'topicAngle' 中并返回
  return {
    json: {
      topicAngle: topicAngle
    }
  };
}

// 如果没找到关键词，可以返回一个空对象或错误提示
return {
  json: {
    topicAngle: '未找到指定的切入点内容'
  }
};

