// **模式**: Run Once for Each Item

try {
  // 1. 获取上游节点输出的纯净JSON字符串
  //    (假设输入字段名为 'output'，如果不同请修改)
  const jsonString = $input.item.json.output;

  // 安全检查：确保输入有效
  if (!jsonString || typeof jsonString !== 'string') {
    throw new Error("输入数据无效或不是字符串。");
  }

  // 2.【核心】直接解析JSON字符串
  const parsedData = JSON.parse(jsonString);

  // 3. 提取需要的两个字段
  const articleContent = parsedData.articleContent;
  const imagePrompts = parsedData.imagePrompts;

  // 4. 安全检查：确保提取的字段存在，防止下游节点出错
  if (articleContent === undefined || imagePrompts === undefined) {
    throw new Error("解析成功，但JSON对象中缺少 'articleContent' 或 'imagePrompts' 字段。");
  }

  // 5. 将提取出的字段作为独立输出返回
  return {
    articleContent: articleContent,
    imagePrompts: imagePrompts
  };

} catch (error) {
  // 6. 容错处理：如果JSON格式意外出错，流程不会中断
  console.error("节点执行失败:", error);
  return {
    error: `节点执行失败: ${error.message}`,
    rawInput: $input.item.json.output // 返回原始输入，便于分析
  };
}

// n8n Code node (JavaScript)
return items.map(item => {
  const j = item.json || {};
  let url = '';

  if (typeof j.url === 'string' && j.url) {
    url = j.url;
  } else if (j.data && typeof j.data === 'object' && typeof j.data.url === 'string') {
    url = j.data.url;
  } else if (typeof j.data === 'string') {
    try {
      const parsed = JSON.parse(j.data);
      if (parsed && typeof parsed.url === 'string') url = parsed.url;
    } catch (e) {
      // ignore parse error
    }
  }

  // 还原 \/
  if (url) url = url.replace(/\\\//g, '/').trim();

  return { json: { 'url': url } };
});

// n8n Code node
return items.map(item => {
  let mediaId = '';

  // 第一种：直接在 json.media_id
  if (typeof item.json?.media_id === 'string') {
    mediaId = item.json.media_id;
  }
  // 第二种：在 json.data.media_id
  else if (typeof item.json?.data === 'object' && typeof item.json.data.media_id === 'string') {
    mediaId = item.json.data.media_id;
  }
  // 第三种：data 是 JSON 字符串
  else if (typeof item.json?.data === 'string') {
    try {
      const parsed = JSON.parse(item.json.data);
      if (parsed && typeof parsed.media_id === 'string') {
        mediaId = parsed.media_id;
      }
    } catch (e) {}
  }

  return {
    json: {
      media_id: mediaId
    }
  };
});
